const KANHA_DATA={id:"kanha",name:"Kanha National Park & Tiger Reserve",location:"Mandla & Balaghat Districts, Madhya Pradesh",established:1955,coreArea:"940 km²",bufferArea:"1,067 km²",totalArea:"2,007 km²",altitude:"450m – 900m",coordinates:{lat:22.34,lng:80.61},quickStats:[{label:"Bengal Tigers",value:"100+",icon:"🐅"},{label:"Hard-Ground Barasingha",value:"800+",icon:"🦌"},{label:"Core Zone Area",value:"940 km²",icon:"🌳"},{label:"Bird Species",value:"300+",icon:"🦅"}],barasingha:{title:"The Hard-Ground Barasingha — Kanha's Conservation Icon",description:"Kanha is globally renowned for rescuing the hard-ground Barasingha (Rucervus duvaucelii branderi) from the brink of extinction. When numbers fell below 66 in the 1970s, a dedicated captive-breeding and habitat-restoration programme brought the population back to over 800 today, making Kanha the only home of this swamp deer subspecies in the world.",facts:["State animal of Madhya Pradesh, found nowhere else in the wild.","Population crashed to under 66 individuals in 1970 before recovery efforts began.","Kanha meadows were specially managed to restore short-grass habitat for the species.","Now classified as Vulnerable, with a stable, closely monitored population."]},tigerReserve:{title:"Project Tiger Reserve Since 1973",description:"Kanha was one of the original nine tiger reserves declared under India's Project Tiger in 1973. Its extensive sal and bamboo forests, interspersed with open meadows, provide an ideal habitat for a thriving Bengal Tiger population that inspired Rudyard Kipling's \"The Jungle Book\".",highlights:["One of the founding reserves of Project Tiger (1973).","Core critical tiger habitat spans 940 km² of protected forest.","Estimated 100+ Bengal Tigers tracked via camera traps and pugmark census.","Buffer zone community programmes support human-wildlife coexistence."]},wildlife:[{name:"Bengal Tiger (Panthera tigris tigris)",status:"Apex Predator",desc:"Kanha supports one of central India's densest tiger populations, roaming sal forests and open meadows across the core zone.",icon:"🐅"},{name:"Hard-Ground Barasingha (Rucervus duvaucelii branderi)",status:"Vulnerable — Flagship Species",desc:"Endemic swamp deer subspecies saved from near-extinction through decades of dedicated conservation at Kanha.",icon:"🦌"},{name:"Indian Leopard (Panthera pardus fusca)",status:"Elusive Predator",desc:"Shares the forest canopy and rocky outcrops with tigers, often spotted along the park's fringes at dusk.",icon:"🐆"},{name:"Dhole (Asiatic Wild Dog)",status:"Endangered Pack Hunter",desc:"Highly social pack hunters that roam Kanha's forests, known locally for coordinated hunting of chital and sambar.",icon:"🐕"},{name:"Gaur (Indian Bison)",status:"Vulnerable Bovine",desc:"India's largest wild bovine, frequently seen grazing in the Kanha and Mukki meadows during winter months.",icon:"🐂"},{name:"Indian Blackbuck",status:"Grassland Antelope",desc:"A small reintroduced population inhabits the open grasslands of Kanha, favouring short-grass meadow habitat.",icon:"🦌"}],flora:{title:"Sal Forests, Bamboo Groves & Grassland Meadows",description:'Kanha\'s vegetation is a mosaic of moist and dry deciduous sal forest, bamboo thickets, and rolling grassland meadows called "maidans". This diversity of habitat supports everything from grazing Barasingha herds to canopy-dwelling langurs.',types:[{name:"Sal Forest (Shorea robusta)",desc:"Dominant tall-canopy tree covering the majority of Kanha's core zone."},{name:"Bamboo Groves",desc:"Dense thickets providing cover and forage along stream valleys."},{name:"Grassland Meadows (Maidans)",desc:"Open short-grass clearings vital for Barasingha and Blackbuck grazing."},{name:"Mixed Deciduous Woodland",desc:"Transitional forest zones with Tendu, Mahua, and Saja trees."}]},forests:{title:"The Maikal Range Forest Landscape",description:"Kanha lies within the Maikal Hills, a spur of the Satpura mountain range, at elevations between 450m and 900m. The undulating terrain of forested ridges and valley meadows creates a mosaic of micro-habitats that supports Kanha's exceptional biodiversity.",zones:[{name:"Kanha Core Zone",desc:"The original protected core with the highest tiger and Barasingha density."},{name:"Mukki Zone",desc:"Remote southwestern zone known for excellent tiger sighting frequency."},{name:"Kisli Zone",desc:"Historic entry zone with dense sal forest and abundant deer species."},{name:"Sarhi Buffer Zone",desc:"Community-managed buffer forest supporting eco-tourism and local livelihoods."}]},safariZones:[{id:"zone-kisli",name:"Kisli Gate Safari",timing:"6:00 AM – 11:00 AM, 3:00 PM – 6:00 PM",highlight:"Best for spotting Barasingha herds grazing in the central meadows.",desc:"The original and most popular entry gate, offering dense sal forest drives and open meadow crossings."},{id:"zone-mukki",name:"Mukki Gate Safari",timing:"6:00 AM – 11:00 AM, 3:00 PM – 6:00 PM",highlight:"Consistently rated the best zone for tiger sightings.",desc:"A remote, less-crowded zone in the southwest with dense forest and a high tiger encounter rate."},{id:"zone-sarhi",name:"Sarhi Gate Safari",timing:"6:00 AM – 11:00 AM, 3:00 PM – 6:00 PM",highlight:"Great for birdwatching and quieter buffer-zone forest trails.",desc:"A buffer zone gate offering community-guided drives through mixed deciduous woodland."},{id:"zone-night-safari",name:"Kanha Museum & Nature Walk",timing:"7:00 AM – 5:00 PM",highlight:"Interpretation centre detailing the Barasingha conservation story.",desc:"A guided walking exploration of Kanha's natural history museum near Kisli gate."}],mapHotspots:[{id:"kisli-gate",name:"Kisli Entrance Gate",x:220,y:150,desc:"Primary entry checkpoint for safaris into the central core zone."},{id:"kanha-meadow",name:"Kanha Central Meadow",x:480,y:300,desc:"Open grassland maidan where Barasingha herds gather to graze."},{id:"mukki-gate",name:"Mukki Entrance Gate",x:700,y:420,desc:"Remote southwestern gate famed for high tiger sighting frequency."},{id:"bamni-dadar",name:"Bamni Dadar Sunset Point",x:620,y:180,desc:"Elevated viewpoint overlooking the Maikal Range forest canopy."},{id:"sarhi-gate",name:"Sarhi Buffer Gate",x:320,y:460,desc:"Community-managed buffer zone gate for birdwatching drives."}],gallery:[{src:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Jungle_safari_-_Kanha_National_Park.jpg/960px-Jungle_safari_-_Kanha_National_Park.jpg",caption:"Jungle safari jeep crossing the open meadows of Kanha National Park."},{src:"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Barasingha_at_Kanha_National_Park.jpg/960px-Barasingha_at_Kanha_National_Park.jpg",caption:"Hard-ground Barasingha stag grazing in a Kanha grassland meadow."},{src:"https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Kanha_Tiger_Reserve.jpg/960px-Kanha_Tiger_Reserve.jpg",caption:"Bengal Tiger resting in the dense sal forest of Kanha Tiger Reserve."},{src:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Sal_forest_Kanha.jpg/960px-Sal_forest_Kanha.jpg",caption:"Towering sal forest canopy along Kanha's core zone trails."}]};"undefined"!=typeof module&&(module.exports={KANHA_DATA:KANHA_DATA});